#requires -Version 5.1
[CmdletBinding(SupportsShouldProcess = $true)]
param(
    [string]$Root = 'B:\University\2027-1\SONORA',
    [string]$RepositoryUrl = 'https://github.com/BrunoRuizJuar/Sonora.git'
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

if (-not (Get-Command git -ErrorAction SilentlyContinue)) {
    throw 'Git is required. Install Git for Windows and run this script again.'
}
$Root = [System.IO.Path]::GetFullPath($Root)
$driveRoot = [System.IO.Path]::GetPathRoot($Root)
if (-not (Test-Path -LiteralPath $driveRoot)) {
    throw "Destination drive does not exist: $driveRoot"
}
if ((Test-Path -LiteralPath $Root) -and -not (Test-Path -LiteralPath $Root -PathType Container)) {
    throw "Destination is not a directory: $Root"
}

# Check existing origin before creating template files.
$gitMarker = Join-Path $Root '.git'
if (Test-Path -LiteralPath $gitMarker) {
    $currentOrigin = & git -C $Root config --get remote.origin.url
    if ($LASTEXITCODE -notin @(0, 1)) { throw 'Cannot inspect Git origin.' }
    if ($currentOrigin) {
        $expected = $RepositoryUrl.TrimEnd('/').ToLowerInvariant()
        $actual = ([string]$currentOrigin).TrimEnd('/').ToLowerInvariant()
        if ($actual -ne $expected) {
            throw "Existing origin differs: $currentOrigin. Review it before running this script."
        }
    }
}

if (-not $PSCmdlet.ShouldProcess($Root, 'Create missing SONORA files and configure Git origin')) {
    return
}
[System.IO.Directory]::CreateDirectory($Root) | Out-Null
if (-not (Test-Path -LiteralPath $gitMarker)) {
    if ([System.IO.Directory]::GetFileSystemEntries($Root).Length -eq 0) {
        & git clone -- $RepositoryUrl $Root
        if ($LASTEXITCODE -ne 0) { throw 'git clone failed. Existing template files were not changed.' }
    } else {
        & git init --initial-branch=main -- $Root
        if ($LASTEXITCODE -ne 0) { throw 'git init failed.' }
        Write-Host 'Existing nonempty folder: Git initialized; remote history will not be merged automatically.'
    }
}
$currentOrigin = & git -C $Root config --get remote.origin.url
if ($LASTEXITCODE -notin @(0, 1)) { throw 'Cannot inspect Git origin.' }
if (-not $currentOrigin) {
    & git -C $Root remote add origin $RepositoryUrl
    if ($LASTEXITCODE -ne 0) { throw 'Cannot add Git origin.' }
}

$encodedPayload = ''
$json = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($encodedPayload))
$files = ConvertFrom-Json -InputObject $json
$created = 0
$preserved = 0
$prefix = $Root.TrimEnd([char[]]@('\', '/')) + [System.IO.Path]::DirectorySeparatorChar
foreach ($item in $files) {
    $relative = $item.path.Replace('/', [System.IO.Path]::DirectorySeparatorChar)
    $target = [System.IO.Path]::GetFullPath((Join-Path $Root $relative))
    if (-not $target.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
        throw "Invalid template path: $($item.path)"
    }
    if (Test-Path -LiteralPath $target) {
        $preserved++
        continue
    }
    $parent = [System.IO.Path]::GetDirectoryName($target)
    [System.IO.Directory]::CreateDirectory($parent) | Out-Null
    $bytes = [Convert]::FromBase64String($item.content_base64)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $actualHash = [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace('-', '').ToLowerInvariant()
    } finally { $sha.Dispose() }
    if ($actualHash -ne $item.sha256) { throw "Invalid template checksum: $($item.path)" }
    # CreateNew preserves a file even if another process creates it after the check.
    $stream = [System.IO.File]::Open($target, [System.IO.FileMode]::CreateNew)
    try { $stream.Write($bytes, 0, $bytes.Length) } finally { $stream.Dispose() }
    $created++
}
# Preserve this self-contained installer alongside the generated project.
$bootstrapTarget = Join-Path $Root 'scripts/Initialize-SONORA.ps1'
if ($PSCommandPath -and -not (Test-Path -LiteralPath $bootstrapTarget)) {
    $selfBytes = [System.IO.File]::ReadAllBytes($PSCommandPath)
    $stream = [System.IO.File]::Open($bootstrapTarget, [System.IO.FileMode]::CreateNew)
    try { $stream.Write($selfBytes, 0, $selfBytes.Length) } finally { $stream.Dispose() }
    $created++
}
Write-Host "SONORA root: $Root"
Write-Host "Created files: $created; preserved existing paths: $preserved"
Write-Host "Origin: $RepositoryUrl"
Write-Host 'Next: read README.md and docs/WINDOWS.md.'
